reg [1:0] read_channel_state;

// B response valid
reg bvalid;

// R response valid
reg rvalid;

// R data
reg [31:0] rdata;

// B response
reg [1:0] bresp;

// R response
reg [1:0] rresp;

// Write channel state
reg [1:0] write_state;

// Read channel state
reg [1:0] read_state;

// Pending write
reg [31:0] pending_write;

// Pending read
reg [31:0] pending_read;

// IRQ set mask
reg [31:0] irq_set_mask;

always_comb begin
    // Determine write valid mask
    wstrb_mask = '0;
    for (int i = 0; i < 4; i++) begin
