    logic [31:0] ctrl_r, ctrl_w;
    logic [31:0] scratch_r, scratch_w;
    logic [31:0] irq_r, irq_w;
    logic [3:0]  status_valid;
    logic [31:0] status_r;
    logic [3:0]  status_bits;

    assign s_axi_awready = !rst && (s_axi_awvalid & ~ctrl_w_valid);
    assign s_axi_arready = !rst && s_axi_arvalid;

    always @(posedge clk) begin
        if (rst) begin
            ctrl_r <= '0;
            ctrl_w <= '0;
            scratch_r <= '0;
            scratch_w <= '0;
            irq_r <= '0;
            irq_w <= '0;
            status_valid <= '0;
            status_r <= '0;
            ctrl_w_valid <= '0;
            scratch_w_valid <= '0;
            irq_set_valid <= '0;
        end
        else begin
            if (s_axi_awvalid & s_axi_awready) begin
                case (s_axi_awaddr)
                    4'd0: ctrl_w <= s_axi_wdata;
                    4'd4: if (s_axi_wstrb[0] & s_axi_wvalid) status_r <= s_axi_wdata;
                    4'd8: scratch_w <= s_axi_wdata;
                    4'dc: irq_w <= s_axi_wdata;
                    default: s_axi_bresp <= 2'b10;
                endcase
            end

            if (s_axi_wvalid & s_axi_wready) begin
                ctrl_w_valid <= 1'b1;
                scratch_w_valid <= 1'b1;
                irq_set_valid <= 1'b1;
                case (s_axi_awaddr)
                    4'd0: if (ctrl_w_valid & ctrl_w[31]) ctrl_r <= ctrl_w;
                    4'd8: if (scratch_w_valid & scratch_w[31]) scratch_r <= scratch_w;
                    4'dc: if (irq_set_valid & irq_w[31]) irq_r <= irq_w;
                endcase
            end

            if (s_axi_bvalid) begin
                case (s_axi_awaddr)
                    4'd0: s_axi_bresp <= 2'b00;
                    4'd4: if (s_axi_wstrb[0] & s_axi_wvalid) s_axi_bresp <= 2'b10;
                    4'd8: s_axi_bresp <= 2'b00;
                    4'dc: s_axi_bresp <= 2'b00;
                    default: s_axi_bresp <= 2'b10;
                endcase
            end

            if (s_axi_rvalid) begin
                s_axi_rdata <= (s_axi_araddr == 4'd4) ? status_r : (s_axi_araddr == 4'd0) ? ctrl_r : (s_axi_araddr == 4'd8) ? scratch_r : (s_axi_araddr == 4'dc) ? irq_r : '0;
                status_valid <= 1'b0;
            end

