module fifo_sync #(
    parameter int W     = 8,   // data width
    parameter int DEPTH = 8    // number of entries, a power of 2
) (
    input  logic                   clk,
    input  logic                   rst,     // synchronous, active high
    input  logic                   wr_en,
    input  logic [W-1:0]           din,
    input  logic                   rd_en,
    output logic [W-1:0]           dout,
    output logic                   full,
    output logic                   empty,
    output logic [$clog2(DEPTH):0] count
);
    logic [W-1:0] q [$:DEPTH-1]; // storage elements
    logic [$clog2(DEPTH):0] q_count;

    assign count = q_count;

    always @(posedge clk) begin
        if (rst) begin
            q_count <= 0;
            q <= '{default: '0};
        end
        else begin
            if (wr_en && ~full) begin
                q[q_count] <= din;
                q_count <= q_count + 1;
            end

            if (rd_en && ~empty) begin
                dout <= q[0];
                q[0] <= '0;
                if (q_count > 1)
                    q[1:] <= q[2:];
                else
                    q <= '{default: '0};
                q_count <= q_count - 1;
            end
        end

        full <= (q_count == DEPTH);
        empty <= (q_count == 0);
    end
endmodule

