    logic signed [2*WIDTH-1:0] prod_reg [3];
    logic [3:0] valid_reg;

    always @(posedge clk) begin
        if (rst) begin
            valid_reg <= 4'd0;
            a_reg[0] <= 0;
            b_reg[0] <= 0;
            prod_reg[0] <= 0;
        end else begin
            if (in_valid) begin
                valid_reg <= 4'd3;
                a_reg[valid_reg] <= a;
                b_reg[valid_reg] <= b;
            end
            if (valid_reg > 0) begin
                prod_reg[valid_reg] <= a_reg[valid_reg] * b_reg[valid_reg];
                if (valid_reg == 2) begin
                    valid_reg <= 4'd0;
                    out_valid <= 1;
                end else begin
                    valid_reg <= valid_reg + 1;
                    out_valid <= 0;
                end
            end
            if (valid_reg == 0 && in_valid) begin
                valid_reg <= 4'd1;
                out_valid <= 0;
            end
            if (valid_reg >= 3) begin
                product <= prod_reg[valid_reg];
            end
        end
    end
endmodule

module rr_arbiter4 (
