    next_last = last + 1;
    next_last = next_last[3] ? 4'd0 : (next_last[2] ? next_last + 1 : (next_last[1] ? next_last + 1 : (next_last[0] ? next_last + 1 : last)));
    gnt_reg <= next_last[3] ? 4'b1000 : (next_last[2] ? 4'b01000 : (next_last[1] ? 4'b00100 : (next_last[0] ? 4'b00010 : 4'b00001)));
