module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    // Registers for each output slot
    logic [5*(4+PAYLOAD_W)-1:0] slot_n, slot_s, slot_e, slot_w, slot_l;
    logic [4:0] slot_valid_n, slot_valid_s, slot_valid_e, slot_valid_w, slot_valid_l;

    logic [1:0] cursor = 2'b00; // Start at N

    logic [4:0] valid_req [5];

    // Routing logic
    always_comb begin
        for (int i = 0; i < 5; i++) begin
            valid_req[i] = '0;
        end

        if (in_valid[0]) begin
            // Route to E if dest_x > X
            if (in_flit[4+PAYLOAD_W+1:4] > X) begin
                valid_req[2] = 1'b1;
            end
            // Route to W if dest_x < X
            else if (in_flit[4+PAYLOAD_W+1:4] < X) begin
                valid_req[3] = 1'b1;
            end
            // Route to N if X coordinates match and dest_y > Y
            else if (in_flit[4+PAYLOAD_W+1:4] == X && in_flit[4+PAYLOAD_W+0:4+PAYLOAD_W-1] > Y) begin
                valid_req[0] = 1'b1;
            end
            // Route to S if X coordinates match and dest_y < Y
            else if (in_flit[4+PAYLOAD_W+1:4] == X && in_flit[4+PAYLOAD_W+0:4+PAYLOAD_W-1] < Y) begin
                valid_req[1] = 1'b1;
            end
            // Route to L if both coordinates match
            else if (in_flit[4+PAYLOAD_W+1:4] == X && in_flit[4+PAYLOAD_W+0:4+PAYLOAD_W-1] == Y) begin
                valid_req[4] = 1'b1;
            end
        end
    end

    // Arbitration logic
    logic [4:0] arbitrator;
    always_comb begin
        arbitrator = '0;
        for (int i = 0; i < 5; i++) begin
            if (valid_req[i] && out_ready[i]) begin
                arbitrator = i;
            end
        end
    end

    // Slot logic
    always @(posedge clk) begin
        if (rst) begin
            slot_n <= '0;
            slot_s <= '0;
            slot_e <= '0;
            slot_w <= '0;
            slot_l <= '0;
            slot_valid_n <= '0;
            slot_valid_s <= '0;
            slot_valid_e <= '0;
            slot_valid_w <= '0;
            slot_valid_l <= '0;
            cursor <= 2'b00;
        end
        else begin
            if (in_valid[arbitrator] && out_ready[arbitrator]) begin
                case (arbitrator)
                    0: slot_n <= in_flit;
                    1: slot_s <= in_flit;
                    2: slot_e <= in_flit;
                    3: slot_w <= in_flit;
                    4: slot_l <= in_flit;
                endcase
                slot_valid_n <= in_valid[0];
                slot_valid_s <= in_valid[1];
                slot_valid_e <= in_valid[2];
                slot_valid_w <= in_valid[3];
                slot_valid_l <= in_valid[4];
                if (cursor == 2'b00) begin
                    cursor <= 2'b01;
                end
                else if (cursor == 2'b01) begin
                    cursor <= 2'b10;
                end
                else if (cursor == 2'b10) begin
                    cursor <= 2'b11;
                end
                else if (cursor == 2'b11) begin
                    cursor <= 2'b00;
                end
            end
            else begin
                case (cursor)
                    2'b00: slot_n <= {slot_n[4+PAYLOAD_W-1:4], slot_n[4+PAYLOAD_W-2:4+PAYLOAD_W-1]};
                    2'b01: slot_s <= {slot_s[4+PAYLOAD_W-1:4], slot_s[4+PAYLOAD_W-2:4+PAYLOAD_W-1]};
                    2'b10: slot_e <= {slot_e[4+PAYLOAD_W-1:4], slot_e[4+PAYLOAD_W-2:4+PAYLOAD_W-1]};
                    2'b11: slot_w <= {slot_w[4+PAYLOAD_W-1:4], slot_w[4+PAYLOAD_W-2:4+PAYLOAD_W-1]};
                endcase
            end
        end
    end

    // Output logic
    always_comb begin
        out_valid = 5'b00000;
        out_flit = '0;
        for (int i = 0; i < 5; i++) begin
            if (slot_valid[i]) begin
                out_valid = 5'b1 << i;
                out_flit = slot_n;
            end
        end
    end

    // Ready logic
    always_comb begin
        in_ready = 5'b00000;
        for (int i = 0; i < 5; i++) begin
            if (valid_req[i]) begin
                in_ready = 5'b1 << i;
            end
        end
    end
endmodule

