    output logic [31:0] crc
);

logic [31:0] remainder;
logic [31:0] temp_remainder;
logic [7:0]  byte;
logic [31:0] mix;

always_ff @(posedge clk) begin
    if (rst) begin
        remainder <= 32'hFFFF_FFFF;
        temp_remainder <= 0;
        out_valid <= 0;
    end else begin
        if (start) begin
            remainder <= 32'hFFFF_FFFF;
            temp_remainder <= remainder;
        end else begin
            if (in_valid) begin
                byte <= data;
                temp_remainder <= {temp_remainder[30], temp_remainder[31], byte, temp_remainder[27:0]};
                remainder <= temp_remainder;
                out_valid <= 1;
            end else begin
                temp_remainder <= remainder;
                out_valid <= 0;
            end
        end
    end
end

always_comb begin
    logic [31:0] temp_mix;

    for (int i = 0; i < 8; i++) begin
        mix = {byte[0], remainder[31:0]};
        temp_mix = mix ^ byte[0];
        remainder = {remainder[30:0], remainder[31]} ^ (temp_mix ^ 32'hEDB8_8320);
        byte = byte >> 1;
    end

    crc = remainder ^ 32'hFFFF_FFFF;
end
