module crc32_stream (
    input  logic        clk,
    input  logic        rst,
    input  logic        start,
    input  logic        in_valid,
    input  logic [7:0]  data,
    output logic        out_valid,
    output logic [31:0] crc
);
    logic [7:0]  in_data;
    logic        in_valid_prev;
    logic        start_prev;
    logic [31:0] remainder;

    always @ (posedge clk) begin
        in_valid_prev <= in_valid;
        start_prev <= start;

        if (rst) begin
            remainder <= 32'hFFFF_FFFF;
            out_valid <= 0;
        end
        else if (in_valid) begin
            remainder[0] <= remainder[0] ^ in_data[0];
            remainder[1] <= remainder[1] ^ in_data[1];
            remainder[2] <= remainder[2] ^ in_data[2];
            remainder[3] <= remainder[3] ^ in_data[3];
            remainder[4] <= remainder[4] ^ in_data[4];
            remainder[5] <= remainder[5] ^ in_data[5];
            remainder[6] <= remainder[6] ^ in_data[6];
            remainder[7] <= remainder[7] ^ in_data[7];

            if (start) begin
                remainder[31:24] <= 32'hEDB8_8320;
                remainder[23:16] <= 32'hEDB8_8320;
                remainder[15:8] <= 32'hEDB8_8320;
                remainder[7:0] <= 32'hEDB8_8320;
            end
            else begin
                if (remainder[0] ^ in_data[0]) begin
                    remainder[31:24] <= 32'hEDB8_8320;
                    remainder[23:16] <= 32'hEDB8_8320;
                    remainder[15:8] <= 32'hEDB8_8320;
                    remainder[7:0] <= 32'hEDB8_8320;
                end
                else begin
                    remainder[31:24] <= {remainder[31:24] >> 1, 1'b0};
                    remainder[23:16] <= {remainder[23:16] >> 1, 1'b0};
                    remainder[15:8] <= {remainder[15:8] >> 1, 1'b0};
                    remainder[7:0] <= {remainder[7:0] >> 1, 1'b0};
                end
            end

            out_valid <= 1;
        end
        else begin
            out_valid <= 0;
        end

        if (rst) begin
            crc <= 0;
        end
        else begin
            crc <= remainder ^ 32'hFFFF_FFFF;
        end
    end

    always_comb begin
        in_data <= data;
    end
endmodule

