module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);
    logic [7:0] temp;

    always_comb begin
        case (op)
            3'b000: begin
                temp = a + b;
                zero = (temp == 8'd0);
                carry = (temp[7]);
            end
            3'b001: begin
                temp = a - b;
                zero = (temp == 8'd0);
                carry = (temp[7]);
            end
            3'b010: begin
                temp = a & b;
                zero = (temp == 8'd0);
                carry = 1'b0;
            end
            3'b011: begin
                temp = a | b;
                zero = (temp == 8'd0);
                carry = 1'b0;
            end
            3'b100: begin
                temp = a ^ b;
                zero = (temp == 8'd0);
                carry = 1'b0;
            end
            3'b101: begin
                temp = 1'b0;
                for (int i = 0; i < 8; i++) begin
                    if (a[i] < b[i]) begin
                        temp = 8'd1;
                        break;
                    end
                end
                zero = (temp == 8'd0);
                carry = 1'b0;
            end
            3'b110: begin
                temp = {1'b0, a[2:0] << b[2:0]};
                zero = (temp == 8'd0);
                carry = 1'b0;
            end
            3'b111: begin
                temp = a >> b[2:0];
                zero = (temp == 8'd0);
                carry = 1'b0;
            end
        endcase
        y = temp;
    end
endmodule

