                y = a >> b[2:0];
                zero = (a == 8'd0);
                carry = 8'd0;
            end
        endcase
    end
endmodule

module alu8 (
    input  logic [7:0] a,
    input  logic [7:0] b,
    input  logic [2:0] op,
    output logic [7:0] y,
    output logic       zero,
    output logic       carry
);
    always_comb begin
        case (op)
            3'b000: begin
                y = a + b;
                zero = (a + b == 8'h00);
                carry = (a[7] & b[7]) | (a[7] & ~b[6]) | (b[7] & a[6]);
            end
            3'b001: begin
                y = a - b;
                zero = (a == b);
                carry = (~a[7] & b[7]) | (a[7] & b[6]);
            end
            3'b010: begin
                y = a & b;
                zero = (a == 8'h00) | (b == 8'h00);
                carry = 1'b0;
            end
            3'b011: begin
                y = a | b;
                zero = (a == 8'h00) & (b == 8'h00);
                carry = 1'b0;
            end
            3'b100: begin
                y = a ^ b;
                zero = (a == b);
                carry = 1'b0;
            end
            3'b101: begin
                y = (a < b) ? 8'h01 : 8'h00;
                zero = (a == 8'h00) | (b == 8'h00);
                carry = 1'b0;
            end
            3'b110: begin
                y = a << b[2:0];
                zero = (a == 8'h00);
                carry = 1'b0;
            end
            3'b111: begin
                y = a >> b[2:0];
                zero = (a == 8'h00);
                carry = 1'b0;
            end
        endcase
    end
endmodule

module seq_detect_1011 (
    input  logic clk,
    input  logic rst,    // synchronous, active high
    input  logic din,    // serial input, one bit per clock
    output logic match
);

logic [3:0] state;

always @(posedge clk) begin
    if (rst) begin
        state <= 4'd0;
        match <= 1'b0;
    end else begin
        state[3] <= din;
        if (state[3] == 1'b1 && state[2] == 1'b0 && state[1] == 1'b1 && state[0] == 1'b1) begin
            match <= 1'b1;
            state <= 4'd0;
        end else begin
            match <= 1'b0;
        end
    end
end

endmodule

