module seq_detect_1011 (
    input  logic clk,
    input  logic rst,    // synchronous, active high
    input  logic din,    // serial input, one bit per clock
    output logic match
);

logic [3:0] state; // 4-bit state machine
logic [3:0] state_count; // count of bits in current state

always @(posedge clk)
begin
    if (rst)
    begin
        state <= 4'b0000;
        state_count <= 4'b0000;
        match <= 1'b0;
    end
    else
    begin
        state_count <= state_count + din;
        if (state_count == 4'b1011)
            match <= 1'b1;
        if (din == 1'b1)
            state <= state + 1;
        else if (state == 4'b1001)
            state <= 4'b0000;
    end
end

endmodule

module seq_detect_1011 (
    input  logic clk,
