logic [3:0] state_count; // count of bits in current state

always @(posedge clk)
begin
    if (rst)
    begin
        state <= 4'b0000;
        state_count <= 4'b0000;
        match <= 1'b0;
    end
    else
    begin
        if (din == 1'b1)
            state <= state + 1;
        else if (state == 4'b1000)
            state <= 4'b0000;
        state_count <= state_count + din;
        if (state == 4'b1011 && state_count == 4'b1111)
            match <= 1'b1;
    end
end

endmodule

module edge_detect (
    input  logic clk,
    input  logic rst,   // synchronous, active high
    input  logic din,
    output logic rise,
    output logic fall
);
logic prev;

always @(posedge clk)
begin
    if (rst)
        begin
            prev <= 0;
            rise <= 0;
            fall <= 0;
        end
    else
        begin
            prev <= din;
            rise <= din & ~prev;
            fall <= ~din & prev;
        end
end
endmodule

module edge_detect (
